    /* F861: a query-parameter API key must not reach a redirect refusal
     * message, so the query and fragment are dropped from the URLs it names. */
    #[test]
    fn test_bhv_errors_077_redacted_url_drops_the_query_and_fragment() {
        let url = reqwest::Url::parse("https://api.example.com/items?api_key=SECRET&x=1#frag")
            .expect("valid url");
        assert_eq!("https://api.example.com/items", redacted_url(&url));
    }

    #[tokio::test]
    async fn test_bhv_errors_078_transport_error_does_not_carry_the_request_url() {
        let err = reqwest::Client::new()
            .get("http://127.0.0.1:1/items?api_key=SECRET")
            .send()
            .await
            .expect_err("nothing listens on port 1");
        let boxed = super::transport_error(err);
        let mut text = boxed.to_string();
        let mut source = boxed.source();
        while let Some(cause) = source {
            text.push_str(&cause.to_string());
            source = cause.source();
        }
        assert!(!text.contains("SECRET"), "got: {}", text);
    }

    /* RFC 9110 section 15.4: the method a redirect hop uses. */
    #[test]
    fn test_bhv_redirects_050_redirect_next_method_follows_rfc_9110() {
        for status in [307u16, 308] {
            for m in ["GET", "HEAD", "POST", "PUT", "PATCH", "DELETE"] {
                assert_eq!(redirect_next_method(status, m), m);
            }
        }
        for status in [301u16, 302] {
            assert_eq!(redirect_next_method(status, "POST"), "GET");
            for m in ["GET", "HEAD", "PUT", "PATCH", "DELETE"] {
                assert_eq!(redirect_next_method(status, m), m);
            }
        }
        assert_eq!(redirect_next_method(303, "HEAD"), "HEAD");
        for m in ["GET", "POST", "PUT", "PATCH", "DELETE"] {
            assert_eq!(redirect_next_method(303, m), "GET");
        }
    }

    /* ── Redirect origin comparison ──
     *
     * The predicate decides whether credentials survive a redirect hop, and
     * traffics in `reqwest::Url`, so it can only be exercised in-crate. A
     * default port written out must not make the same origin look foreign. */
    #[test]
    fn test_bhv_redirects_030_same_origin_treats_an_explicit_default_port_as_the_same_origin() {
        let parse = |s: &str| reqwest::Url::parse(s).unwrap();
        assert!(same_origin(
            &parse("https://example.com/a"),
            &parse("https://example.com:443/b")
        ));
        assert!(same_origin(
            &parse("http://example.com:80/a"),
            &parse("http://example.com/b")
        ));
        assert!(same_origin(
            &parse("https://Example.COM/a"),
            &parse("https://example.com/b")
        ));
    }

    /* redirects037: the credentials are kept on a redirect that stays on the origin, and the
     * explicit default port is that same origin. */
    #[test]
    fn test_bhv_redirects_037_a_redirect_to_the_explicit_default_port_keeps_authorization() {
        let parse = |s: &str| reqwest::Url::parse(s).unwrap();
        assert!(same_origin(
            &parse("https://example.com/start"),
            &parse("https://example.com:443/landed")
        ));
        assert!(same_origin(
            &parse("http://example.com/start"),
            &parse("http://example.com:80/landed")
        ));
    }

    #[test]
    fn test_bhv_redirects_034_same_origin_rejects_a_different_scheme_host_or_port() {
        let parse = |s: &str| reqwest::Url::parse(s).unwrap();
        assert!(!same_origin(
            &parse("https://example.com/a"),
            &parse("http://example.com/a")
        ));
        assert!(!same_origin(
            &parse("https://example.com/a"),
            &parse("https://other.example.com/a")
        ));
        assert!(!same_origin(
            &parse("https://example.com/a"),
            &parse("https://example.com:8443/a")
        ));
        assert!(!same_origin(
            &parse("http://example.com:80/a"),
            &parse("https://example.com:443/a")
        ));
    }

